import { graphql, Link } from "gatsby";
import React from "react";
import ProductDetail from "./product-detail";
import SeO from '../components/seo'

import { HEADER_IMG, HEADER_DESCR, CRUMB } from "../config/shop";


export default function Product({ data }) {
  const p = data.merchantProduct;
  const siteUrl = data.site.siteMetadata.siteUrl;
  //const productUrl = `${siteUrl}/shop/${p.slug}`;
  const availability = {
    "in stock": "https://schema.org/InStock",
    "preorder": "https://schema.org/PreOrder",
    "out of stock": "https://schema.org/OutOfStock"
  }[String(p.availability).toLowerCase()] || "https://schema.org/InStock";

  return (
      <div style={{padding:`1em`}}>
	 <img src={ HEADER_IMG } alt={ HEADER_DESCR } style={{"margin":"auto","display":"block","height":"3em"}} />
        <ul className="breadcrumb" >
        <li><Link to="/">Home</Link></li>
        <li><Link to={`/${CRUMB}`}>{`${CRUMB.charAt(0).toUpperCase()}${CRUMB.slice(1)}`}</Link></li>
        <li>{p.title}</li>
        </ul>
	  <ProductDetail
      title={p.title}
      images={[p.imageUrl]}
      price={p.price}
      originalPrice={p.originalPrice}
      currency={p.currency}
      description={p.description}
      specs={p.specs}
      availability={p.availability}
      buyUrl={p.link}
    /></div>
  );
}

export function Head({ data, location }) {
  const p = data.merchantProduct;
  const siteUrl = data.site.siteMetadata.siteUrl;
  const productUrl = `${siteUrl}/${CRUMB}/${p.slug}`;
  const schema = {
    "@context": "https://schema.org",
    "@type": "Product",
    "@id": `${productUrl}#product`,
    "name": p.title,
    "description": p.description,
    "url": productUrl,
    "image": p.imageUrl ? [p.imageUrl] : undefined,
    "sku": p.merchantId,
    "category": p.category,
    "brand": { "@type": "Brand", "name": p.brand || "Wisdel.uk" },
    "offers": {
      "@type": "Offer",
      "url": productUrl,
      "price": p.price,
      "priceCurrency": p.currency,
      "availability": ({
        "in stock": "https://schema.org/InStock",
        "preorder": "https://schema.org/PreOrder",
        "out of stock": "https://schema.org/OutOfStock"
      })[String(p.availability).toLowerCase()] || "https://schema.org/InStock",
      "itemCondition": "https://schema.org/NewCondition"
    }
  };

  return (
    <SeO
      title={p.title}
      description={p.description}
      image={p.imageUrl}
      imageAlt={p.title}
      what="product"
      schemaMarkup={schema}
      pathname={location.pathname}
    />
  );
}

export const query = graphql`
  query ($id: String!) {
    site {
      siteMetadata {
	siteUrl
      }
    }
    merchantProduct(id: { eq: $id }) {
      merchantId
      title
      description
      price
      currency
      availability
      brand
      category
      imageUrl
      link
      slug
    }
  }
`;
